import { ActionDefinition } from '../../../Action'
import {
    StringColumn,
    ReferenceColumn,
    BooleanColumn,
    IntegerColumn,
    DocumentIdColumn,
    ChoiceColumn,
    DurationColumn,
} from '../../../../db'

export const submitCatalogItemRequest = ActionDefinition({
    $id: 'c7a04c607312001098e194596bf6a72a',
    name: 'Submit Catalog Item Request',
    description: `<p>Creates a requested item [sc_req_item] on a Service Catalog Request [sc_req]. The request can be configured to be a blocking or non-blocking task.</p>
<p>Pass request variables to the task to provide additional information or to allow the fulfiller to modify the variables.</p>`,
    category: 'bf2f2fec73f70300b61e66476bf6a774',
    inputs: {
        catalog_item_inputs: StringColumn({
            label: 'Catalog Item Inputs',
            maxLength: 32000000,
        }),
        delivery_address: StringColumn({
            label: 'Delivery Address',
            maxLength: 4000,
        }),
        sysparm_requested_for: ReferenceColumn({
            label: 'Requested for',
            referenceTable: 'sys_user',
        }),
        schedule: ReferenceColumn({
            label: 'Schedule',
            referenceTable: 'cmn_schedule',
        }),
        duration: DurationColumn({
            label: 'Duration',
            default: '1970-01-01 00:00:00',
        }),
        _snc_dont_fail_on_error: BooleanColumn({
            label: "Don't fail on error",
        }),
        catalog_item: ReferenceColumn({
            label: 'Catalog Item',
            mandatory: true,
            referenceTable: 'sc_cat_item',
        }),
        timeout_flag: BooleanColumn({
            label: 'Enable timeout',
        }),
        sysparm_quantity: IntegerColumn({
            label: 'Quantity',
            default: 1,
        }),
        special_instructions: StringColumn({
            label: 'Special Instructions',
            maxLength: 4000,
        }),
        wait_for_completion: BooleanColumn({
            label: 'Wait for Completion',
        }),
    },
    outputs: {
        error_message: StringColumn({
            label: 'Error Message',
            maxLength: 10000,
        }),
        requested_item: DocumentIdColumn({
            label: 'Requested Item',
            dependent: 'catalog_item',
            tableReference: true,
        }),
        status: ChoiceColumn({
            label: 'Status',
            maxLength: 32,
            default: '0',
            choices: {
                0: {
                    label: 'Success',
                },
                1: {
                    label: 'Error',
                    sequence: 1,
                },
                2: {
                    label: 'Timeout',
                    sequence: 2,
                },
            },
        }),
    },
})
